use crate::component::Component;
use anyhow::Result;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::sync::atomic::{AtomicU32, Ordering};
use tracing::{debug, info};

/// 📤 Component response builder - eliminates repetitive JSON construction
/// Generated by #[component_response] macro with button-specific fields
#[crate::component_response]
struct ComponentResponse {
    // Button-specific response fields
    click_count: u32,
    text: String,
    amount: u32,
    // Common ComponentResponse fields auto-injected by macro:
    // success: bool, action: String, version: u64, component_id: String,
    // timestamp: Option<String>, message: Option<String>, error: Option<String>
}

/// ⚙️ Button component configuration
#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct Config {
    /// Initial button text
    #[serde(default = "default_button_text")]
    pub text: String,
}

fn default_button_text() -> String {  "Button".to_string()  }


/// 🔘 Button Component - Works with macro-generated infrastructure
#[crate::component(template = "button.hbs", config = "Config")]
pub struct Button {
    // User fields only - macro handles all framework fields
    text: String,
    click_count: AtomicU32,
}

impl Button {
    /// 🔧 Called after component creation - initialize user fields
    /// NOTE: This is called by macro-generated constructor
    pub async fn new_component(&mut self) -> Result<()> {
        // Initialize user fields from config
        self.text = self.cfg.text.clone();
        self.click_count = AtomicU32::new(0);

        // Try to load saved state
        let state_key = format!("button:{}:state", self.id());
        if let Ok(Some(state)) = self.load_state(&state_key).await {
            if let Some(text) = state.get("text").and_then(|v| v.as_str()) {
                self.text = text.to_string();
            }
            if let Some(count) = state.get("click_count").and_then(|v| v.as_u64()) {
                self.click_count.store(count as u32, Ordering::SeqCst);
            }
            debug!("📖 Loaded button state for '{}'", self.id());
        }
        
        info!("🔘 Button component '{}' initialized", self.id());
        Ok(())
    }

    /// 🖱️ Handle button click - routed by macro
    pub async fn click(&mut self) -> Result<Value> {
        info!("🖱️ Button '{}' clicked! 🎉", self.id());
        let new_count = self.click_count.fetch_add(1, Ordering::SeqCst) + 1;
        self.increment_version();
        
        if let Err(e) = self.save_component_state().await {
            tracing::warn!("Failed to save button state: {}", e);
        }

        Ok(ComponentResponse::success("click", self.id(), self.current_version())
            .with_click_count(new_count)
            .with_timestamp()
            .to_json())
    }

    /// 📝 Set button text - routed by macro
    pub async fn set_text(&mut self, text: &str) -> Result<Value> {
        if text.is_empty() {
            return Ok(ComponentResponse::error("Text cannot be empty").to_json());
        }

        info!("📝 Setting button '{}' text to: '{}'", self.id(), text);
        self.text = text.to_string();
        self.increment_version();
        
        if let Err(e) = self.save_component_state().await {
            tracing::warn!("Failed to save button state: {}", e);
        }

        Ok(ComponentResponse::success("set_text", self.id(), self.current_version())
            .with_text(text.to_string())
            .to_json())
    }

    /// 🔄 Reset button count - routed by macro
    pub async fn reset(&mut self) -> Result<Value> {
        info!("🔄 Resetting button '{}'", self.id());
        self.click_count.store(0, Ordering::SeqCst);
        self.increment_version();
        
        if let Err(e) = self.save_component_state().await {
            tracing::warn!("Failed to save button state: {}", e);
        }

        Ok(ComponentResponse::success("reset", self.id(), self.current_version())
            .with_click_count(0)
            .with_message("Button reset successfully")
            .to_json())
    }

    /// ➕ Increment by custom amount - routed by macro
    pub async fn increment(&mut self, amount: u64) -> Result<Value> {
        let amount = amount as u32;
        if amount == 0 {
            return Ok(ComponentResponse::error("Increment amount must be greater than 0").to_json());
        }

        info!("➕ Incrementing button '{}' by {}", self.id(), amount);
        let new_count = self.click_count.fetch_add(amount, Ordering::SeqCst) + amount;
        self.increment_version();
        
        if let Err(e) = self.save_component_state().await {
            tracing::warn!("Failed to save button state: {}", e);
        }

        Ok(ComponentResponse::success("increment", self.id(), self.current_version())
            .with_amount(amount)
            .with_click_count(new_count)
            .with_message(&format!("Incremented by {amount} successfully"))
            .to_json())
    }

    /// 📊 Get current count - routed by macro
    pub async fn get(&self, key: &str) -> Result<Value> {
        match key {
            "count" => Ok(json!(self.click_count.load(Ordering::SeqCst))),
            "text" => Ok(json!(self.text)),
            _ => Ok(json!({
                "error": format!("Unknown key: {}", key),
                "available_keys": ["count", "text"]
            }))
        }
    }

    // ================================================================================
    // 🔧 HELPER METHODS
    // ================================================================================

    /// 💾 Save component state using macro-generated storage helpers
    async fn save_component_state(&self) -> Result<()> {
        let state = json!({
            "text": self.text,
            "click_count": self.click_count.load(Ordering::SeqCst),
            "version": self.current_version(),
            "last_updated": chrono::Utc::now().to_rfc3339()
        });
        
        let state_key = format!("button:{}:state", self.id());
        self.save_state(&state_key, state).await
    }
}

